// HandleProductSearch handles the product search requests and renders the results page.
func HandleProductSearch(w http.ResponseWriter, r *http.Request) {
	// Extract the keyword from the URL query parameters
	keyword := r.URL.Query().Get("keyword")

	// Escape the keyword to prevent Cross-Site Scripting (XSS) attacks
	safeKeyword := html.EscapeString(keyword)

	// Set the response content type to HTML
	w.Header().Set("Content-Type", "text/html; charset=utf-8")

	// Write the HTML response
	fmt.Fprintf(w, `<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Search Results</title>
    <!-- Analytics support placeholder -->
    <script>
        // Example analytics tracking
        window.addEventListener('DOMContentLoaded', (event) => {
            console.log("Analytics: User searched for keyword: %s");
        });
    </script>
</head>
<body>
    <h2>Search Results: %s</h2>
</body>
</html>`, safeKeyword, safeKeyword)
}

func main() {
	// Register the handler
	http.HandleFunc("/search", HandleProductSearch)

	// Start the HTTP server
	fmt.Println("Server is running on http://localhost:8080/search?keyword=your_keyword")
	http.ListenAndServe(":8080", nil)
}

