// HandleProductSearch handles the product search requests and renders the results page.
func HandleProductSearch(w http.ResponseWriter, r *http.Request) {
	// Extract the keyword from the URL query parameters
	keyword := r.URL.Query().Get("keyword")

	// Escape the keyword to prevent XSS attacks when rendering in HTML
	escapedKeyword := html.EscapeString(keyword)

	// Analytics support: log the search query on the server side
	log.Printf("Analytics: User searched for keyword: %q", keyword)

	// Set the response content type to HTML
	w.Header().Set("Content-Type", "text/html; charset=utf-8")

	// Render the HTML page
	fmt.Fprintf(w, `<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <title>Search Results</title>
    <script>
        // Client-side analytics support
        console.log("Analytics Event: Product Search", { keyword: %q });
    </script>
</head>
<body>
    <h2>Search Results: %s</h2>
    <!-- Product listing would go here -->
</body>
</html>`, keyword, escapedKeyword)
}

func main() {
	// Register the handler
	http.HandleFunc("/search", HandleProductSearch)

	// Start the server
	log.Println("Server is running on http://localhost:8080/search?keyword=your_keyword")
	if err := http.ListenAndServe(":8080", nil); err != nil {
		log.Fatalf("Server failed to start: %v", err)
	}
}

