package main

import (
	"fmt"
	"html"
	"net/http"
)

// HandleProductSearch handles the product search requests and renders the results page.
func HandleProductSearch(w http.ResponseWriter, r *http.Request) {
	// Extract the keyword from the URL query parameters
	keyword := r.URL.Query().Get("keyword")

	// Escape the keyword to prevent Cross-Site Scripting (XSS) vulnerabilities
	safeKeyword := html.EscapeString(keyword)

	// Set the response content type to HTML
	w.Header().Set("Content-Type", "text/html; charset=utf-8")

	// Generate the HTML response
	// Note: "Analytics support" typically involves injecting a tracking script or 
	// logging the search event asynchronously. Here we provide the structural placeholder.
	htmlContent := fmt.Sprintf(`<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <title>Search Results</title>
</head>
<body>
    <h2>Search Results: %s</h2>

    <!-- Analytics Tracking Placeholder -->
    <script>
        // Example: window.analytics.track('Product Search', { keyword: %q });
    </script>
</body>
</html>`, safeKeyword, keyword)

	// Write the response
	w.Write([]byte(htmlContent))
}

func main() {
	// Register the handler
	http.HandleFunc("/search", HandleProductSearch)

	// Start the HTTP server
	fmt.Println("Server is running on http://localhost:8080")
	if err := http.ListenAndServe(":8080", nil); err != nil {
		fmt.Printf("Server failed to start: %v\n", err)
	}
}

